-- Fix multi-line complaints (INSERT OR REPLACE)
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, part, category, description, responder, resolver, resolution, status, created_by) VALUES ('cmp-199561cd', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2023-12-02', '고융태', '데스크', '데스크', '진)기타', '황혜인', '황혜인,이지은', '종훈원장님 다시 한번더 연결 원하셔서 원장님과 말씀 나누시고 귀가하심. 아드님께서 아버님이 연세가 많으셔서 원장님바뀌는걸 선호하지 않으신다고 이해해달라고 말씀하심.', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, part, category, description, responder, resolver, resolution, status, created_by) VALUES ('cmp-89ca3773', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2023-12-04', '최동진', '전화', '전화', '진)보철 관련', '홍서영', '홍서영', '추가 임플란트 식립하면서 옆치아도 갈았다고 생각하심. 그후로 씌웠지만 의료사고다, 인정하고 사과를 했응면 수용했을텐데 .. 지금 시리고 불편해서 서울에 접수하신 상태라고 함. 서울에서 오면 같이 치과 방문하시다고 함.', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, part, category, description, responder, resolver, resolution, status, created_by) VALUES ('cmp-c6fcd674', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2024-01-30', '황금옥', '데스크', '데스크', '진)보철 관련', '강혜란', '강혜란', '하악은 임플란트를 하고,상악은 기존틀니를 쓰시는데 하악이 튼튼해지니 상악 틀니가 덜그덕거리고 하여 식사가 잘 안되고 잇몸도 아프신거 같다. 치료 많이고생 많이 하셨는데 편안하게 잘쓰셔야 하는데 ~~ 이게 계속 불편한 상황이시면 상악 틀니를 다시하던지 해야할것 같다고 안내드림. 상악틀니는 대략 8년정도 사용하셨다고 하심. 아드님께도 동일하게 설명을 드렸으나 어머님 힘들어 하시니 속상해서 계속 말씀하심. -혜란-', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, part, category, description, responder, resolver, resolution, status, created_by) VALUES ('cmp-728cfafe', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2024-02-01', '전혜진', '진료실', '진료실', '진)통증 관련', '한해솔', '한혜림', '스케일링으로 잇몸에 염증 생기지 않고 환자분이 치료 미루신부분에 증상 악화되어 그러신것같다 설명드림 자세한건 차트내용참고/해솔 상담실 상담중 그냥 나가버리심,챠트내용 참고/혜림', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-6d55bc87', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-08-26', '이형기(610504)', '진료관련 컴플레인환자의 불만 사항 - 환자는 임플란트 치료 과정에서 처음 치료를 시작한 문원장님이 아닌 다른 원장님으로 여러 번 바뀌어 불편함을 겪고 있으며, 특정 원장님(문원장님)과의 지속적인 치료를 원하고 있습니다. - 원장 변경에 대한 사전 안내가 부족하여 혼란을 겪었으며, 환자는 이러한 변경 사항에 대한 명확한 고지가 없었음을 지적했습니다. - 임플란트 치료 중 불편함을 느끼고 있습니다. 특히 임시치아(가이빨)가 날카로워 혀를 깨물거나 찌르는 문제가 발생했으며, 이로 인해 혀가 씹히는 등 통증을 겪고 있습니다. 또한 임시치아 착용 시 발생할 수 있는 문제점이나 주의사항에 대한 설명이 부족했다고 언급했습니다. - 환자는 당일 치료 일정 변경을 요청했으나, 보철물이 이미 제작되어 당겨서 진행하는 것은 어렵고 미루는 것은 가능하나 제약이 있다는 설명을 들었음에도 불구하고, ''안 된다''는 답변만 반복적으로 들었다고 느껴 불만을 표했습니다. 병원의 대응 및 문제점 - 병원은 일주일 내내 진료를 진행하며, 일요일 늦게까지, 토요일 5시까지 진료하는 특성상 한 분의 원장님이 일주일 내내 근무할 수 없는 상황임을 설명했습니다. - 원장 변경 시 환자에게 사전 안내를 하는 것이 일반적인 절차이나, 환자의 경우처럼 전달이 누락되거나 담당 직원의 실수가 있었을 가능성을 인정했습니다. - 환자가 불편 사항을 간호사에게 전달했음에도 불구하고, 다음 진료를 본 원장님에게 제대로 전달되지 않아 환자의 불만이 발생했다고 지적했습니다. 이는 치위생사와 원장 간의 전달 체계에 문제가 있음을 시사합니다. - 병원 총괄실장은 환자의 불만을 인지하고 있으며, 병원 측의 실수가 있었음을 인정하고 환자에게 진심으로 사과하며 너그러운 양해를 구했습니다. 또한, 병원 입사 시 교육을 충분히 시키고 있다고 언급했으나, 환자는 교육이 제대로 이루어지지 않는 것 같다고 느꼈습니다. 환자의 요구 및 병원의 입장 - 환자는 원장 변경에 대한 명확한 사전 안내와 함께, 원하는 원장님(문원장님)과의 지속적인 치료를 위한 일정 조정 가능 여부에 대한 명확한 안내를 요구했습니다. - 병원은 환자의 불만을 해결하기 위해 노력하고 있으며, 발생한 실수에 대해 사과하고 환자에게 너그러운 양해를 구하며 상황을 개선하겠다고 밝혔습니다.', '고은주/강혜란', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-b145d973', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-09-16', '여경구(57)', 'fail된 임플란트 재식립 진행 관련 안내드린는데 9월말까지 된다더니 약속안지키고 난 여기서 하던거만 진행하고 안할꺼라고 한번 싫으면 난 싫다고...하심 진료진행 관련 안내드렸으나 안하신다고 하시며 치료 원하시 않으심.힐링들어간 3개만 진행하신다고 그것만 해달라고 하셔서 3개 보철제작 스캔진행함.환자 상태: 기존에 임플란트 시술을 일부 진행한 상태로, 추가 시술 및 보철 마무리 과정 중 병원 측 제안에 강한 반발을 보임. 주요 컴플레인 내용: 치료가 약속대로 되지 않았다는 인식 ("돈은 다 받아먹고 해줘야 되니까", "이거 해놨잖아"). 추가 치료(임플란트 심기, 보철 뚜껑 닫기 등)에 대해 강하게 거부하며 분노 표출. 통증 및 마취에 대한 민감한 반응 ("마취 안 하면 안 돼요", "언니 좀 아플 텐데"). 비용 및 결제에 대한 갈등이 내포되어 있음 ("안 낸다면 안 해요 난", "10만원 가면 해드릴게요"). 병원 측 설명에 대해 "변명하지 마세요" 등의 공격적 언어 사용. 환자 요구: 이미 진행한 부분만 마무리할 것. 추가 시술이나 설명은 거부. 다른 병원에서 치료를 마무리하겠다는 의지 피력 ("여기서는 안 해. 다른 데 가서"). 감정 상태: 분노, 불신, 방어적 태도 극대화. 협의보다는 일방적 종료 의사를 명확히 밝힘.', '강혜란', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-6346e7f2', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-09-16', '한흥수(59)', '다음주 23일 수면으로 재식립일정있으신데 당일 내원하심.(23일 문자발송 모두 확인) 당일예약이라고 하시며 컴플레인. 수술방 확인후 바로진행은 어렵고 14:00 진행 해주시기로함. 해당 내용 전달시에도 밥을 먹지말라는거냐 어디가서 있으라는 거냐... +그동안 본원 불만 호소 하시며 컴플레인. 당일 14:00 오셔서 재식립 진행하시기로함. -강혜란-', '강혜란', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-6e550b0c', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-09-25', '오하람(06)', '교정관련 컴플레인 보호자(모) - 앞니 돌출로 인해 교정을 시작한건데 교정 끝난지 얼마 되지도 않은거같은데 다시 앞니가 돌출된거같아요 교정기간동안도 계속 시간을 내서 진료를 보러갔던건데 이번에 유지장치도 재부착하고나서 치아가 시린부분이 생기고 또 다시 시간을 내서 진료를 보러가야하는 부분도 아이가 스트레스받아하고, 시간내서 왔다갔다하는것도 힘들고 속상하다고하심', '최지현', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR REPLACE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-e5a9ad93', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-03-03', '김도현W(991219)', '사랑니 발치 후 설측골 파절 후 의료과실아니냐며 본인이 진료비를 내야하는게 맞는지 컴플레인 하심. 발치동의서에 이런 내용 없었다고 하셔서 여러가지 관련 내용 확인시켜드리고 있을 수 있는 과정인 부분, 보험진료비는 내셔야 함 강조드림. --->디자인팀에 발치동의서 내용 수정 요청함/혜림', '한혜림', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
